pts5i=[(1,7,4,2),(2,10,0,8),(3,1,2,5),(4,10,1,2),(5,1,4,8)]
data=pts1i+pts2i+pts3i+pts4i+pts5i
# Test linear modular formulas with simple position/value features.
features={
 'r':lambda r,c,i:r,'c':lambda r,c,i:c,'i':lambda r,c,i:i,
 'rc':lambda r,c,i:r*c,'ri':lambda r,c,i:r*i,'ci':lambda r,c,i:c*i,
 'r2':lambda r,c,i:r*r,'c2':lambda r,c,i:c*c,'i2':lambda r,c,i:i*i,
}
import itertools
sol=[]
keys=list(features)
for n in range(1,4):
 for ks in itertools.combinations(keys,n):
  for co in itertools.product(range(3),repeat=n):
   for b in range(3):
    if all((sum(a*features[k](r,c,i) for a,k in zip(co,ks))+b)%3==(o-2)//3 for r,c,i,o in data):
     sol.append((ks,co,b))
print('solutions',sol[:20],len(sol))

dims=[(11,11),(8,9),(8,6),(11,10),(5,12)]
groups=[pts1i,pts2i,pts3i,pts4i,pts5i]
records=[]
for (H,W),pts in zip(dims,groups):
 for rank,(r,c,i,o) in enumerate(pts): records.append(dict(r=r,c=c,i=i,o=o,H=H,W=W,N=len(pts),rank=rank))
funcs={
 'r':lambda d:d['r'],'c':lambda d:d['c'],'i':lambda d:d['i'],'H':lambda d:d['H'],'W':lambda d:d['W'],
 'N':lambda d:d['N'],'rank':lambda d:d['rank'],'rc':lambda d:d['r']*d['c'],'ri':lambda d:d['r']*d['i'],'ci':lambda d:d['c']*d['i'],
}
sol=[]
for n in range(1,4):
 for ks in itertools.combinations(funcs,n):
  for co in itertools.product(range(3),repeat=n):
   for b in range(3):
    if all((sum(a*funcs[k](d) for a,k in zip(co,ks))+b)%3==(d['o']-2)//3 for d in records): sol.append((ks,co,b))
print(sol[:20],len(sol))

funcs2=dict(funcs)
for div in range(2,13):
 funcs2[f'r//{div}']=lambda d,div=div:d['r']//div
 funcs2[f'c//{div}']=lambda d,div=div:d['c']//div
 funcs2[f'i//{div}']=lambda d,div=div:d['i']//div
 funcs2[f'r%{div}']=lambda d,div=div:d['r']%div
 funcs2[f'c%{div}']=lambda d,div=div:d['c']%div
sol=[]
for n in range(1,3):
 for ks in itertools.combinations(funcs2,n):
  for co in itertools.product(range(3),repeat=n):
   for b in range(3):
    if all((sum(a*funcs2[k](d) for a,k in zip(co,ks))+b)%3==(d['o']-2)//3 for d in records): sol.append((ks,co,b))
print(sol[:20],len(sol))

funcs3=dict(funcs)
funcs3.update({'idx':lambda d:(d['r']-1)*d['W']+d['c']-1,'before7':lambda d:(d['r']-1)*d['W']+d['c']-1-d['rank'],
               'after7':lambda d:d['H']*d['W']-((d['r']-1)*d['W']+d['c'])- (d['N']-d['rank']-1),
               'above':lambda d:d['r']-1,'left':lambda d:d['c']-1,'below':lambda d:d['H']-d['r'],'right':lambda d:d['W']-d['c']})
sol=[]
for n in range(1,4):
 for ks in itertools.combinations(funcs3,n):
  for co in itertools.product(range(3),repeat=n):
   for b in range(3):
    if all((sum(a*funcs3[k](d) for a,k in zip(co,ks))+b)%3==(d['o']-2)//3 for d in records): sol.append((ks,co,b))
print(sol[:20],len(sol))

# Add nearest-neighbor and border-distance features.
for d in records:
 same=[e for e in records if e['H']==d['H'] and e['W']==d['W'] and e['N']==d['N']]
 # safer use group lookup
for (H,W),pts in zip(dims,groups):
 ds=[d for d in records if d['H']==H and d['W']==W and d['N']==len(pts)]
 for d in ds:
  others=[e for e in ds if e is not d]
  d['near']=min(abs(d['r']-e['r'])+abs(d['c']-e['c']) for e in others)
  d['cheb']=min(max(abs(d['r']-e['r']),abs(d['c']-e['c'])) for e in others)
  d['edge']=min(d['r']-1,d['c']-1,H-d['r'],W-d['c'])
funcs4=dict(funcs3)
funcs4.update({'near':lambda d:d['near'],'cheb':lambda d:d['cheb'],'edge':lambda d:d['edge']})
sol=[]
for n in range(1,4):
 for ks in itertools.combinations(funcs4,n):
  for co in itertools.product(range(3),repeat=n):
   for b in range(3):
    if all((sum(a*funcs4[k](d) for a,k in zip(co,ks))+b)%3==(d['o']-2)//3 for d in records): sol.append((ks,co,b))
print(sol[:20],len(sol))

