j=0
for r in range(len(out2)):
 for c in range(len(out2[0])):
  if out2[r][c]!=7:
   out2[r][c]=[2,8,5][j%3];j+=1
print(out2)

for name,pts,start in [('d1',pts1i,1),('d3',pts3i,1)]:
 print(name)
 for j,(r,c,i,o) in enumerate(pts):
  k=(o-2)//3
  print(j,(r,c),'k',k,'rank expected',(start+j)%3,'row expected',(start+r-pts[0][0])%3)

# add within-row features and rerun compact linear search
for (H,W),pts in zip(dims,groups):
 ds=[d for d in records if d['H']==H and d['W']==W and d['N']==len(pts)]
 for d in ds:
  rowmates=sorted([e for e in ds if e['r']==d['r']],key=lambda e:e['c'])
  d['nrow']=len(rowmates);d['jrow']=rowmates.index(d);d['jright']=len(rowmates)-1-d['jrow']
  d['occupied_rank']=sorted(set(e['r'] for e in ds)).index(d['r'])
funcs5=dict(funcs4)
funcs5.update({k:(lambda d,k=k:d[k]) for k in ['nrow','jrow','jright','occupied_rank']})
sol=[]
for n in range(1,4):
 for ks in itertools.combinations(funcs5,n):
  for co in itertools.product(range(3),repeat=n):
   for b in range(3):
    if all((sum(a*funcs5[k](d) for a,k in zip(co,ks))+b)%3==(d['o']-2)//3 for d in records): sol.append((ks,co,b))
print(sol[:30],len(sol))

pts7i=[(2,1,0,2),(2,4,8,5),(3,6,6,8),(7,3,3,8),(8,5,5,2)]
groups.append(pts7i);dims.append((9,6))
# recreate records helper with within row
records=[]
for (H,W),pts in zip(dims,groups):
 for rank,(r,c,i,o) in enumerate(pts):
  rowmates=[p for p in pts if p[0]==r]
  records.append(dict(r=r,c=c,i=i,o=o,H=H,W=W,N=len(pts),rank=rank,nrow=len(rowmates),jrow=sorted(rowmates,key=lambda p:p[1]).index((r,c,i,o))))
funcs6={k:(lambda d,k=k:d[k]) for k in ['r','c','i','H','W','N','rank','nrow','jrow']}
funcs6.update({'absri':lambda d:abs(d['r']-d['i']),'absci':lambda d:abs(d['c']-d['i']),'absrc':lambda d:abs(d['r']-d['c']),
               'sumri':lambda d:d['r']+d['i'],'sumci':lambda d:d['c']+d['i'],'diffri':lambda d:d['r']-d['i'],'diffci':lambda d:d['c']-d['i']})
sol=[]
for n in range(1,4):
 for ks in itertools.combinations(funcs6,n):
  for co in itertools.product(range(3),repeat=n):
   for b in range(3):
    if all((sum(a*funcs6[k](d) for a,k in zip(co,ks))+b)%3==(d['o']-2)//3 for d in records): sol.append((ks,co,b))
print(sol[:20],len(sol))
